INSERT INTO marcas(nome,slug,pais_origem,site_oficial,descricao,ativo) VALUES ('IVECO','iveco','Itália','https://www.ivecobus.com/latam-pt','Fabricante de chassis e veículos para transporte de passageiros.',1) ON DUPLICATE KEY UPDATE site_oficial=VALUES(site_oficial),descricao=COALESCE(NULLIF(descricao,''),VALUES(descricao));
INSERT INTO familias(marca_id,nome,descricao,tipo_veiculo,ativo) SELECT id,'IVECO BUS','Chassis urbanos, escolares e de fretamento IVECO BUS.','onibus',1 FROM marcas WHERE slug='iveco' ON DUPLICATE KEY UPDATE descricao=COALESCE(NULLIF(familias.descricao,''),VALUES(descricao)),tipo_veiculo='onibus';
INSERT INTO familias(marca_id,nome,descricao,tipo_veiculo,ativo) SELECT id,'IVECO BUS Multienergia','Chassis IVECO BUS a gás, biometano e elétricos.','onibus',1 FROM marcas WHERE slug='iveco' ON DUPLICATE KEY UPDATE descricao=COALESCE(NULLIF(familias.descricao,''),VALUES(descricao)),tipo_veiculo='onibus';
