INSERT INTO modelos(familia_id,nome,slug,descricao,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'IVECO BUS 10-190','iveco-bus-10-190','Especificações atualizadas a partir de fonte oficial pública.','IVECO FPT NEF 4, 4.485 cm³, Proconve P8','186 cv (137 kW) @ 2.500 rpm','610 Nm @ 1.200-2.100 rpm','Eaton ESBO-6206 B manual, 6 marchas','10.500 kg',NULL,'4,56:1','{"tipo_veiculo":"Ônibus","energia":"Diesel","configuracao":"4x2","entre_eixos":"4.500 / 4.800","emissoes":"Proconve P8 / Euro 6","peso_ordem_marcha":"3.200 / 3.220 kg","cmt":"13.000 kg","mercado":"Urbano, intermunicipal e escolar ORE 2","fonte_oficial":"https://www.ivecobus.com/latam-pt/onibus-rural-escolar","conferido_em":"2026-09-16","documento_auditoria":"/public/assets/documents/modelos/iveco-20260915-iveco-bus-folheto-chassi-mirco-10-190.pdf"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='iveco' AND f.nome='IVECO BUS' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='iveco' AND (mx.slug='iveco-bus-10-190' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('IVECO BUS 10-190')))) LIMIT 1;
INSERT INTO modelo_especificacoes_tecnicas(modelo_id,chave,rotulo,valor,unidade,fonte_url,conferido_em) SELECT m.id,'pbt','PBT','10.500 kg',NULL,'https://www.ivecobus.com/latam-pt/onibus-rural-escolar','2026-09-16' FROM modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='iveco' AND (m.slug='iveco-bus-10-190' OR LOWER(TRIM(m.nome))=LOWER(TRIM('IVECO BUS 10-190')) ) LIMIT 1 ON DUPLICATE KEY UPDATE rotulo=VALUES(rotulo),valor=CASE WHEN valor IS NULL OR TRIM(valor)='' OR LOWER(TRIM(valor)) IN ('não informado','nao informado','n/d') THEN VALUES(valor) ELSE valor END,fonte_url=CASE WHEN valor IS NULL OR TRIM(valor)='' THEN VALUES(fonte_url) ELSE fonte_url END,conferido_em=CASE WHEN valor IS NULL OR TRIM(valor)='' THEN VALUES(conferido_em) ELSE conferido_em END;
