INSERT INTO modelo_documentos(modelo_id,tipo,titulo,arquivo,url_origem,fonte_pagina,ativo) SELECT m.id,'ficha_tecnica','Documento técnico oficial - IVECO BUS 17-E BEV','/public/assets/documents/modelos/iveco-20260915-release-iveco-bus-chassi-17-e-bev---latbus-2024-20240806t192124t721-3fduqmuiofuxvztvmbnq1ja1.pdf','https://www.ivecogroup.com/media/brand_press_releases/2024/SOUTH-AMERICA-(BR-PORTUG)/Iveco-Bus/17-e_bev__o_chassi_eltrico_da_iveco_bus_desenvolvido_para_a_realidade_do_brasil_e_da_amrica_latina_20240806T192144T864_3fduqmuiofuxvztvmbnq1ja1','https://www.ivecogroup.com/media/brand_press_releases/2024/SOUTH-AMERICA-(BR-PORTUG)/Iveco-Bus/17-e_bev__o_chassi_eltrico_da_iveco_bus_desenvolvido_para_a_realidade_do_brasil_e_da_amrica_latina_20240806T192144T864_3fduqmuiofuxvztvmbnq1ja1',1 FROM modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='iveco' AND (m.slug='iveco-bus-17-e-bev' OR LOWER(TRIM(m.nome))=LOWER(TRIM('IVECO BUS 17-E BEV'))) LIMIT 1 ON DUPLICATE KEY UPDATE titulo=COALESCE(NULLIF(titulo,''),VALUES(titulo)),arquivo=COALESCE(NULLIF(arquivo,''),VALUES(arquivo)),url_origem=COALESCE(NULLIF(url_origem,''),VALUES(url_origem)),fonte_pagina=COALESCE(NULLIF(fonte_pagina,''),VALUES(fonte_pagina));
INSERT INTO modelos(familia_id,nome,slug,descricao,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'IVECO Daily Minibus 45-160 Fretamento','iveco-daily-minibus-45-160-fretamento','Especificações atualizadas a partir de fonte oficial pública.',NULL,'160 cv',NULL,NULL,NULL,NULL,NULL,'{"tipo_veiculo":"Minibus","energia":"Diesel","configuracao":"17+1 lugares","mercado":"Fretamento","situacao_comercial":"Configuração lançada comercialmente em agosto de 2026","observacao_fonte":"Ficha técnica brasileira completa não localizada na página pública","fonte_oficial":"https://www.ivecogroup.com/media/brand_press_releases/2026/SOUTH-AMERICA-(BR-PORTUG)/Iveco-Bus/iveco_bus_anuncia_investimento_de_r_150_milhes_e_amplia_portflio_paraacelerar_crescimento_na_amrica_latina_20260811T151057T911_krk3a2jwbotf1semw3w5wujl","conferido_em":"2026-09-16"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='iveco' AND f.nome='Daily Minibus' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='iveco' AND (mx.slug='iveco-daily-minibus-45-160-fretamento' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('IVECO Daily Minibus 45-160 Fretamento')))) LIMIT 1;
