INSERT INTO modelos(familia_id,nome,slug,descricao,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'IVECO Daily Minibus Hi-Matic','iveco-daily-minibus-hi-matic','Especificações atualizadas a partir de fonte oficial pública.',NULL,NULL,NULL,'Hi-Matic automática, 8 velocidades',NULL,NULL,NULL,'{"tipo_veiculo":"Minibus","energia":"Diesel","mercado":"Fretamento e executivo","situacao_comercial":"Lançamento comercial em agosto de 2026","observacao_fonte":"A denominação de configuração e demais dados dependem da proposta comercial","fonte_oficial":"https://www.ivecogroup.com/media/brand_press_releases/2026/SOUTH-AMERICA-(BR-PORTUG)/Iveco-Bus/iveco_bus_anuncia_investimento_de_r_150_milhes_e_amplia_portflio_paraacelerar_crescimento_na_amrica_latina_20260811T151057T911_krk3a2jwbotf1semw3w5wujl","conferido_em":"2026-09-16"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='iveco' AND f.nome='Daily Minibus' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='iveco' AND (mx.slug='iveco-daily-minibus-hi-matic' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('IVECO Daily Minibus Hi-Matic')))) LIMIT 1;
