-- Drive Learn - atualização auditada do catálogo de ônibus IVECO.
-- Gerado em 2026-09-16; idempotente; preenche lacunas sem substituir dados válidos já cadastrados.
-- Não confundir peso/tara do chassi com PBT. Protótipos e lançamentos futuros ficam inativos.
SET NAMES utf8mb4;
START TRANSACTION;

CREATE TABLE IF NOT EXISTS schema_migrations (versao VARCHAR(80) NOT NULL PRIMARY KEY, descricao VARCHAR(255) NOT NULL, aplicado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS modelo_especificacoes_tecnicas (modelo_id BIGINT UNSIGNED NOT NULL,chave VARCHAR(80) NOT NULL,rotulo VARCHAR(120) NOT NULL,valor VARCHAR(255) NOT NULL,unidade VARCHAR(30) NULL,fonte_url VARCHAR(700) NULL,conferido_em DATE NULL,PRIMARY KEY(modelo_id,chave),INDEX idx_met_chave_030(chave),CONSTRAINT fk_met_modelo_030 FOREIGN KEY(modelo_id) REFERENCES modelos(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;



-- IVECO BUS 10-190
UPDATE modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id SET m.motor=CASE WHEN m.motor IS NULL OR TRIM(m.motor)='' OR LOWER(TRIM(m.motor)) IN ('não informado','nao informado','n/d') THEN 'IVECO FPT NEF 4, 4.485 cm³, Proconve P8' ELSE m.motor END,m.potencia=CASE WHEN m.potencia IS NULL OR TRIM(m.potencia)='' OR LOWER(TRIM(m.potencia)) IN ('não informado','nao informado','n/d') THEN '186 cv (137 kW) @ 2.500 rpm' ELSE m.potencia END,m.torque=CASE WHEN m.torque IS NULL OR TRIM(m.torque)='' OR LOWER(TRIM(m.torque)) IN ('não informado','nao informado','n/d') THEN '610 Nm @ 1.200-2.100 rpm' ELSE m.torque END,m.transmissao=CASE WHEN m.transmissao IS NULL OR TRIM(m.transmissao)='' OR LOWER(TRIM(m.transmissao)) IN ('não informado','nao informado','n/d') THEN 'Eaton ESBO-6206 B manual, 6 marchas' ELSE m.transmissao END,m.pbt=CASE WHEN m.pbt IS NULL OR TRIM(m.pbt)='' OR LOWER(TRIM(m.pbt)) IN ('não informado','nao informado','n/d') THEN '10.500 kg' ELSE m.pbt END,m.relacao_reducao=CASE WHEN m.relacao_reducao IS NULL OR TRIM(m.relacao_reducao)='' OR LOWER(TRIM(m.relacao_reducao)) IN ('não informado','nao informado','n/d') THEN '4,56:1' ELSE m.relacao_reducao END,m.descricao=CASE WHEN m.descricao IS NULL OR TRIM(m.descricao)='' OR LOWER(TRIM(m.descricao)) IN ('não informado','nao informado','n/d') THEN 'Especificações atualizadas a partir de fonte oficial pública.' ELSE m.descricao END,m.especificacoes=JSON_MERGE_PATCH('{"tipo_veiculo":"Ônibus","energia":"Diesel","configuracao":"4x2","entre_eixos":"4.500 / 4.800","emissoes":"Proconve P8 / Euro 6","peso_ordem_marcha":"3.200 / 3.220 kg","cmt":"13.000 kg","mercado":"Urbano, intermunicipal e escolar ORE 2","fonte_oficial":"https://www.ivecobus.com/latam-pt/onibus-rural-escolar","conferido_em":"2026-09-16","documento_auditoria":"/public/assets/documents/modelos/iveco-20260915-iveco-bus-folheto-chassi-mirco-10-190.pdf"}',COALESCE(m.especificacoes,JSON_OBJECT())) WHERE ma.slug='iveco' AND (m.slug='iveco-bus-10-190' OR LOWER(TRIM(m.nome))=LOWER(TRIM('IVECO BUS 10-190')));

